  out.tradingPlans=raw.tradingPlans.map(p=>normalizePlan(p,out.settings.instruments));
  if(!out.tradingPlans.length) out.tradingPlans=[normalizePlan(clone(defaultState.tradingPlans[0]),out.settings.instruments)];
