function complianceMetricSwitch(){return `<div class="metric-switch compliance-switch"><span>Unidad</span>${[['r','R'],['ticks','Ticks'],['usd','US$']].map(([v,l])=>`<button class="seg-btn ${complianceViewState.unit===v?'active':''}" data-tr-onclick="complianceSetUnit('${v}')">${l}</button>`).join('')}<i></i><span>Base</span>${[['gross','Bruto'],['net','Neto']].map(([v,l])=>`<button class="seg-btn ${complianceViewState.basis===v?'active':''}" data-tr-onclick="complianceSetBasis('${v}')">${l}</button>`).join('')}</div>`;}
