function dashboardComplianceRulesPanel(ops){const prevUnit=complianceViewState.unit,prevBasis=complianceViewState.basis;complianceViewState.unit='r';complianceViewState.basis='net';const rows=complianceRuleStats(ops).sort((a,b)=>a.rate-b.rate).slice(0,7);complianceViewState.unit=prevUnit;complianceViewState.basis=prevBasis;return `<section class="card panel dashboard-custom-panel"><div class="panel-title"><div><h3>Cumplimiento por regla</h3><small>Reglas con menor tasa de cumplimiento</small></div><button class="btn tiny ghost" data-tr-onclick="navigate('compliance')">Abrir</button></div><div class="dashboard-compliance-list">${rows.length?rows.map(r=>`<div><span><strong>${esc(r.name)}</strong><small>n=${r.n} · ${r.fail.length} fallos</small></span><i><b style="width:${r.rate}%"></b></i><em>${r.rate.toFixed(0)}%</em></div>`).join(''):'<div class="empty">Sin checklist evaluado.</div>'}</div></section>`;}
