/* Scatter MAE/MFE: solo usa estados explícitamente medidos, incluido un 0 real. */
labMaeMfeScatter=function(ops){
  const xMode=labState.scatterX,key=xMode==='mae'?'mae':'mfe';
  const measured=ops.filter(o=>dqMetricMeasured(o,key));
  const points=measured.map(o=>({x:Number(o[key]),y:opMetricValue(o,'usd',labState.basis),win:o.result==='win',label:`${o.contract||''} ${fmtDate(o.entryDate)}`})).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));
  const q=dqV28ModuleQuality(ops,[key],`El scatter excluye ${Math.max(0,ops.length-measured.length)} operación(es) sin ${key.toUpperCase()} medido.`,{always:true,context:'MAE / MFE'});
  return `<section class="card panel lab-module lab-span-2"><div class="panel-title"><div><h3>Scatter · ${xMode.toUpperCase()} vs Resultado</h3><small>Verde = ganadora · rojo = perdedora · Y siempre en US$ para lectura económica</small></div><select class="select compact-select" data-tr-onchange="setLabScatterX(this.value)"><option value="mae" ${xMode==='mae'?'selected':''}>MAE</option><option value="mfe" ${xMode==='mfe'?'selected':''}>MFE</option></select></div>${q}<div class="lab-scatter-wrap">${scatterSvg(points,xMode)}</div><div class="lab-note">Solo entran operaciones cuyo ${xMode.toUpperCase()} está marcado como <strong>Medido</strong>. Un 0.00R explícitamente medido sí es un dato real.</div></section>`;
};

