async function v314StoreGet(store,id){const db=await v314Db();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),req=tx.objectStore(store).get(id);req.onsuccess=()=>{db.close();resolve(req.result||null);};req.onerror=()=>{const e=req.error;db.close();reject(e);};});}
