function v314CsvSplit(line){let out=[],cur='',q=false;for(let i=0;i<String(line).length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(c===';'&&!q){out.push(cur);cur='';}else cur+=c;}out.push(cur);return out;}
