    if(last<minLast)minLast=last;if(last>maxLast)maxLast=last;
    if(totalAggregateTicks<minPnlTicks)minPnlTicks=totalAggregateTicks;if(totalAggregateTicks>maxPnlTicks)maxPnlTicks=totalAggregateTicks;
