  let calibration='';if(set){const det=set.offsetDetection,matched=det&&Number.isFinite(det.matches)?`${det.matches}/${set.rows.length} ejecuciones con precio localizado`:'desfase manual';calibration=`<section class="card panel md-calibration"><div class="panel-title"><div><h3>Calibración entrada → salida</h3><small>${esc(set.sourceFile)}${meta?` × ${esc(meta.sourceFile)}`:''}</small></div><button class="btn small" data-tr-onclick="v314RecalculateExec()">Auto detectar y recalcular</button></div><div class="md-cal-controls"><div><span>Histórico activo</span><strong>${meta?esc(meta.instrument):'—'}</strong><small>${meta?Number(meta.rowCount).toLocaleString('es-ES')+' ticks':'selecciona histórico'}</small></div><div><span>Desfase Grid → UTC</span><strong>${v314OffsetText(set.offsetHours)}</strong><small>${esc(matched)}</small></div><label><span>Ajuste manual (horas)</span><div><input id="v314-offset" class="input" type="number" min="-12" max="14" step="0.5" value="${Number.isFinite(Number(set.offsetHours))?Number(set.offsetHours):0}"><button class="btn small" data-tr-onclick="v314ApplyManualOffset()">Aplicar</button></div></label><div><span>Trades reconstruidos</span><strong>${(set.results||[]).filter(x=>x.entryMatch&&x.exitMatch).length}/${set.trades?.length||0}</strong><small>${set.unclosed?`${set.unclosed} posición(es) sin cerrar en el CSV`:'todas las posiciones cerradas'}</small></div></div>${v315CalibrationTable(set,meta)}</section>`;}
  return top+status+datasets+calibration;
