/* ===== V31.19 · Event Delegation compatibility commands =====
   Historical inline handlers that mutated lexical UI state directly now call this
   explicit command boundary. Keeping those writes here lets the delegated runtime
   remain eval-free and prevents it from reaching app lexical state by string name. */
function trLegacyStateCommand(command,a,b){
  switch(command){
    case 'ops-risk-policy': opsViewState.riskPolicy=String(a||'raw');render();return true;
    case 'gallery-reset': galleryViewState={q:'',setup:'',vd:'',nr:'',result:'',direction:'',label:'',context:''};gallerySelected=[];render();return true;
    case 'journal-set': if(a==='emotion'||a==='behavior')journalViewState[a]=String(b??'');render();return true;
    case 'journal-reset': journalViewState={q:'',emotion:'',behavior:'',discipline:'',status:''};render();return true;
    case 'lab-clear': if(a&&Object.prototype.hasOwnProperty.call(labState,a))labState[a]='';render();return true;
    case 'lab-clear-range': labState.rMin='';labState.rMax='';render();return true;
    case 'lab-compare-clear': labStudiesUi.compareId='';render();return true;
    case 'reports-compare-open': reportsViewState.tab='compare';navigate('reports');return true;
    case 'dashboard-draft-clear': dashboardCustomizeDraft=null;return true;
    case 'editing-clear':
      if(a==='compliance')editingComplianceRuleId=null;
      else if(a==='review')editingReviewNoteId=null;
      else if(a==='goal')editingGoalId=null;
      else if(a==='mistake')editingMistakeId=null;
      return true;
    default: console.warn('[Trading Research · UI command] Acción desconocida',command);return false;
  }
}
window.trLegacyStateCommand=trLegacyStateCommand;
/* ===== END V31.19 compatibility commands ===== */

